using OcctSharp.BoundedText;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class BoundedTextTransformTests {
 [Fact]public void UnicodeTransformsPersistActualDocumentText()=>BatchBNBoundedTextWorkflow.Run();
 [Theory][InlineData(BoundedTextOperation.Concatenate)][InlineData(BoundedTextOperation.Append)][InlineData(BoundedTextOperation.Assign)][InlineData(BoundedTextOperation.Overwrite)]public void ExplicitLengthAsciiAndUnicodeTransformsAreIndependent(BoundedTextOperation op){foreach(var encoding in new[]{BoundedTextEncoding.Ascii,BoundedTextEncoding.Unicode}){string source=encoding==BoundedTextEncoding.Ascii?"abcd":"中文🚀";string other=encoding==BoundedTextEncoding.Ascii?"XY":"汉字";var result=BoundedTextTransforms.Compute(new(source,op,other,encoding,Position:1));Assert.Equal(op==BoundedTextOperation.Assign?other:op==BoundedTextOperation.Overwrite?other+source[2..]:source+other,result.Text);Assert.Equal(1,result.InputOrdinal);Assert.Equal(result.Text.Length,result.Utf16Units);Assert.Equal(System.Text.Encoding.UTF8.GetByteCount(result.Text),result.Utf8Bytes);}}
 [Fact]public void OverwriteGrowsAtEndAndReplacesWholeSurrogatePair(){Assert.Equal("中文🚀汉",BoundedTextTransforms.Compute(new("中文🚀",BoundedTextOperation.Overwrite,"汉",Position:5)).Text);Assert.Equal("中替位文",BoundedTextTransforms.Compute(new("中🚀文",BoundedTextOperation.Overwrite,"替位",Position:2)).Text);Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中🚀文",BoundedTextOperation.Overwrite,"汉",Position:2)));Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中🚀文",BoundedTextOperation.Overwrite,"汉",Position:3)));}
 [Fact]public void UnicodeBmpReplacementRemovalAndTokenKeepSupplementaryCharacters(){Assert.Equal("汉🚀汉",BoundedTextTransforms.Compute(new("中🚀中",BoundedTextOperation.ReplaceCharacter,Position:'中',Character:'汉')).Text);Assert.Equal("🚀",BoundedTextTransforms.Compute(new("中🚀中",BoundedTextOperation.RemoveCharacter,Position:'中')).Text);Assert.Equal("🚀",BoundedTextTransforms.Compute(new("中文,,🚀;结束",BoundedTextOperation.Token,",;",Position:2)).Text);Assert.Equal("",BoundedTextTransforms.Compute(new("中,文",BoundedTextOperation.Token,",",Position:3)).Text);}
 [Fact]public void EmptyValuesAndEmptyBatchReturnIndependentValues(){Assert.Empty(BoundedTextTransforms.ComputeBatch([]));Assert.Equal("",BoundedTextTransforms.Compute(new("",BoundedTextOperation.Append)).Text);Assert.Equal("",BoundedTextTransforms.Compute(new("中文",BoundedTextOperation.Assign)).Text);Assert.Empty(BoundedTextTransforms.ComputeBatch([],new(MaximumOutputBytes:0)));}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void InvalidNulAndSurrogatesAreRejected(int kind){string value=kind==0?"a\0b":new string((char)(kind==1?0xD800:0xDC00),1);if(kind==0)Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new(value,BoundedTextOperation.Append)));else Assert.Throws<System.Text.EncoderFallbackException>(()=>BoundedTextTransforms.Compute(new(value,BoundedTextOperation.Append)));}
 [Fact]public void AsciiRejectsUnicodeAndUnicodeOnlyOperations(){Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中文",BoundedTextOperation.Append,Encoding:BoundedTextEncoding.Ascii)));Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("abc",BoundedTextOperation.Prepend,"x",BoundedTextEncoding.Ascii)));}
 [Fact]public void InvalidPositionsCharactersAndSeparatorsAreRejected(){Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中",BoundedTextOperation.Overwrite,"汉",Position:3)));Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中",BoundedTextOperation.ReplaceCharacter,Position:0)));Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("🚀",BoundedTextOperation.RemoveCharacter,Position:0xD83D)));Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中",BoundedTextOperation.Token,"")));Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中🚀文",BoundedTextOperation.Token,"🚀")));Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new("中",BoundedTextOperation.Token,",",Position:0)));}
 [Fact]public void ExpansionChecksUtf8BytesBeforeNativeMutation(){string source=new('x',400000);Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new(source,BoundedTextOperation.ReplaceCharacter,Position:'x',Character:'中')));string sourceLimit=new('x',1048576);Assert.Equal(sourceLimit,BoundedTextTransforms.Compute(new(sourceLimit,BoundedTextOperation.Append)).Text);Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.Compute(new(sourceLimit,BoundedTextOperation.Append,"x")));}
 [Fact]public void LazyBatchStopsAfterBudgetPlusOneAndPublishesNothing(){int moves=0;IEnumerable<BoundedTextTransform> Infinite(){while(true){moves++;yield return new("中",BoundedTextOperation.Append);}}Assert.Throws<ArgumentException>(()=>BoundedTextTransforms.ComputeBatch(Infinite(),new(MaximumItems:3)));Assert.Equal(4,moves);}
 [Fact]public void BatchValidatesEveryItemAndCumulativeReservationBeforePublishing(){IReadOnlyList<BoundedTextCopy>? result=null;Assert.Throws<ArgumentException>(()=>result=BoundedTextTransforms.ComputeBatch([new("中",BoundedTextOperation.Append),new("文",BoundedTextOperation.Append)],new(MaximumOutputBytes:5)));Assert.Null(result);Assert.Throws<ArgumentException>(()=>result=BoundedTextTransforms.ComputeBatch([new("中",BoundedTextOperation.Append),new("坏\0",BoundedTextOperation.Append)]));Assert.Null(result);var copied=BoundedTextTransforms.ComputeBatch([new("中",BoundedTextOperation.Append),new("文",BoundedTextOperation.Append)],new(MaximumOutputBytes:6));Assert.Collection(copied,x=>Assert.Equal(1,x.InputOrdinal),x=>Assert.Equal(2,x.InputOrdinal));}
}
